import{_ as e,C as r,o as h,c as n,j as d,a as s,E as o,ah as l}from"./chunks/framework.DuX8SFU5.js";const u=JSON.parse('{"title":"AM_NODE_V2 — даташит","description":"","frontmatter":{"title":"AM_NODE_V2 — даташит","pdf":"/pdf/AM_NODE_V2_datasheet.pdf","pdfStyle":"datasheet","pageClass":"datasheet-page","preliminary":true},"headers":[],"relativePath":"am_node_v2/datasheet.md","filePath":"am_node_v2/datasheet.md"}'),i={name:"am_node_v2/datasheet.md"};function S(c,t,b,p,N,A){const a=r("AssetImage");return h(),n("div",null,[t[0]||(t[0]=d("h2",{id:"_1-описание",tabindex:"-1"},[s("1. Описание "),d("a",{class:"header-anchor",href:"#_1-описание","aria-label":'Permalink to "1. Описание"'},"​")],-1)),t[1]||(t[1]=d("p",null,"AM_NODE_V2 — плата-носитель узла ввода-вывода для мобильной техники. Она объединяет вход питания с измерением напряжения и тока, четыре канала управления клапанами и нагрузками с контролем ручной команды, восемь дискретных промышленных линий, четыре токовых входа 4–20 мА и интерфейсы связи. Контроллер устанавливается одним из двух модулей: FMU-модуль на STM32H753 (исполнение H7) или модуль uNODE V2 на STM32F103 (исполнение F103).",-1)),o(a,{name:"am_node_v2.webp",alt:"AM_NODE_V2, вид платы"}),t[2]||(t[2]=l(`<p>Характеристики, помеченные «уточняется», не подтверждены измерениями или финальной документацией платы.</p><h2 id="_2-возможности" tabindex="-1">2. Возможности <a class="header-anchor" href="#_2-возможности" aria-label="Permalink to &quot;2. Возможности&quot;">​</a></h2><ul><li>Вход питания 24 В через XT30, встроенный DC/DC 5 В и локальные стабилизаторы 3,3 В.</li><li>Измерение входного напряжения (делитель) и тока (INA169, шунт 1 мОм).</li><li>4 канала LOAD для электрогидроклапанов и других нагрузок: включение/выключение или ШИМ.</li><li>Измерение тока и напряжения на выходе каждого канала и на входе ручной команды (INA228).</li><li>Bypass: при отказе или отключённой плате штатная команда проходит на клапан через нормально замкнутое реле.</li><li>8 линий SENS на MAX14906 (4 в исполнении F103): дискретные входы PNP/NPN с программным питанием каждого датчика и диагностикой.</li><li>4 входа C_SENS для датчиков 4–20 мА (INA228, шунт 2 Ом): ток, давление или перемещение.</li><li>CAN с трансиверами TJA1042: 2 шины в исполнении H7, 1 шина в исполнении F103.</li><li>Ethernet 10/100 (LAN8742A, RMII) и USB-C (USB 2.0 FS) в исполнении H7.</li><li>Прошивка с протоколом DroneCAN, параметры и обновление по CAN.</li></ul><h2 id="_3-исполнения" tabindex="-1">3. Исполнения <a class="header-anchor" href="#_3-исполнения" aria-label="Permalink to &quot;3. Исполнения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Исполнение</th><th>Контроллер</th><th>Доступно</th><th>Недоступно</th></tr></thead><tbody><tr><td>H7</td><td>FMU-модуль, STM32H753IIK6</td><td>LOAD1–4, bypass, SENS1–8, C_SENS1–4, CAN1, CAN2, Ethernet, USB-C</td><td>—</td></tr><tr><td>F103</td><td>uNODE MODULE V2, STM32F103T8</td><td>LOAD1–4, bypass, SENS1–4 (только входы), C_SENS1–4, CAN1 через трансивер модуля</td><td>SENS5–8, CAN2, Ethernet, USB-C</td></tr></tbody></table><p>Модули контроллера взаимоисключающие: одновременная установка обоих не допускается.</p><h2 id="_4-характеристики" tabindex="-1">4. Характеристики <a class="header-anchor" href="#_4-характеристики" aria-label="Permalink to &quot;4. Характеристики&quot;">​</a></h2><h3 id="_4-1-электрические" tabindex="-1">4.1. Электрические <a class="header-anchor" href="#_4-1-электрические" aria-label="Permalink to &quot;4.1. Электрические&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Мин.</th><th>Тип.</th><th>Макс.</th><th>Ед.</th><th>Примечание</th></tr></thead><tbody><tr><td>Напряжение питания Vin</td><td>—</td><td>24</td><td>уточняется</td><td>В</td><td>Вход DC/DC-модуля 5,5–30 В; предел платы определяется защитой и разъёмами</td></tr><tr><td>Шина 5 В</td><td>—</td><td>5</td><td>—</td><td>В</td><td>DC/DC-модуль LMR16030</td></tr><tr><td>Логические шины</td><td>—</td><td>3,3</td><td>—</td><td>В</td><td>Локальные LDO</td></tr><tr><td>Ток канала LOAD</td><td>—</td><td>—</td><td>уточняется</td><td>А</td><td>Ограничен модулем ключа, разъёмом и медью платы</td></tr><tr><td>Шунт измерения LOAD</td><td>—</td><td>20</td><td>—</td><td>мОм</td><td>Настраивается параметром</td></tr><tr><td>Входной ток C_SENS</td><td>4</td><td>—</td><td>20</td><td>мА</td><td>Шунт 2 Ом на землю</td></tr><tr><td>Скорость CAN</td><td>—</td><td>—</td><td>1</td><td>Мбит/с</td><td>Задаётся прошивкой</td></tr><tr><td>Ethernet</td><td>—</td><td>—</td><td>100</td><td>Мбит/с</td><td>Только H7</td></tr><tr><td>USB</td><td>—</td><td>12</td><td>—</td><td>Мбит/с</td><td>USB 2.0 Full Speed, только H7</td></tr></tbody></table><h3 id="_4-2-механические" tabindex="-1">4.2. Механические <a class="header-anchor" href="#_4-2-механические" aria-label="Permalink to &quot;4.2. Механические&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение</th></tr></thead><tbody><tr><td>Размер платы</td><td>82,5 × 98,5 мм</td></tr><tr><td>Высота сборки</td><td>уточняется: зависит от модуля контроллера</td></tr><tr><td>Крепление</td><td>монтажные отверстия по чертежу платы</td></tr><tr><td>Масса</td><td>уточняется</td></tr></tbody></table><h3 id="_4-3-условия-эксплуатации" tabindex="-1">4.3. Условия эксплуатации <a class="header-anchor" href="#_4-3-условия-эксплуатации" aria-label="Permalink to &quot;4.3. Условия эксплуатации&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение</th></tr></thead><tbody><tr><td>Рабочая температура</td><td>уточняется</td></tr><tr><td>Степень защиты</td><td>обеспечивается корпусом; плата без корпуса не защищена</td></tr><tr><td>Покрытие платы</td><td>уточняется</td></tr></tbody></table><h2 id="_5-функциональная-схема" tabindex="-1">5. Функциональная схема <a class="header-anchor" href="#_5-функциональная-схема" aria-label="Permalink to &quot;5. Функциональная схема&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Питание 24 В ──► XT30 Vin1 ──┬── DC/DC 5 В ──► 3,3 В</span></span>
<span class="line"><span>                             ├── измерение Vin и тока ──► контроллер</span></span>
<span class="line"><span>                             └── LOAD1…LOAD4 ◄── модули ключей + INA228 ◄── контроллер (GPIO, I²C)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Контроллер (H7 или F103)</span></span>
<span class="line"><span>   ├── SPI ──► MAX14906 ×4 ──► SENS1…SENS8</span></span>
<span class="line"><span>   ├── I²C ──► INA228 ×12 ──► токи LOAD и C_SENS1…C_SENS4</span></span>
<span class="line"><span>   ├── GPIO ─► LOAD, BYPASS</span></span>
<span class="line"><span>   ├── CAN ──► TJA1042 ──► CAN1 (и CAN2 в H7)</span></span>
<span class="line"><span>   └── H7: RMII ──► LAN8742A ──► Ethernet; USB FS ──► USB-C</span></span></code></pre></div><h2 id="_6-разъемы-и-распиновка" tabindex="-1">6. Разъёмы и распиновка <a class="header-anchor" href="#_6-разъемы-и-распиновка" aria-label="Permalink to &quot;6. Разъёмы и распиновка&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Разъём</th><th>Тип</th><th>Исполнение</th><th>Назначение</th></tr></thead><tbody><tr><td>Vin1</td><td>XT30PW-M</td><td>оба</td><td>Основное питание: <code>+</code> — Vin, <code>−</code> — GND</td></tr><tr><td>LOAD1…LOAD4</td><td>JST-XH, 4 конт.</td><td>оба</td><td>Нагрузка и линия ручной команды</td></tr><tr><td>SENS1…SENS8</td><td>JST-XH, 3 конт.</td><td>оба</td><td>Дискретные датчики</td></tr><tr><td>C_SENS1…C_SENS4</td><td>JST-XH, 3 конт.</td><td>оба</td><td>Датчики 4–20 мА</td></tr><tr><td>CAN1, CAN2</td><td>JST-GH, 4 конт.</td><td>CAN2 только H7</td><td>CAN_H, CAN_L, GND</td></tr><tr><td>CAN1-A/B, CAN2-A/B</td><td>Molex 502585, 6 конт.</td><td>CAN2 только H7</td><td>CAN и питание для шлейфового подключения</td></tr><tr><td>ETH</td><td>JST-GH, 8 конт.</td><td>H7</td><td>Ethernet 10/100</td></tr><tr><td>USB</td><td>USB-C</td><td>H7</td><td>Сервисное подключение, USB 2.0 FS</td></tr></tbody></table><h3 id="load1-load4" tabindex="-1">LOAD1…LOAD4 <a class="header-anchor" href="#load1-load4" aria-label="Permalink to &quot;LOAD1…LOAD4&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th><th>Описание</th></tr></thead><tbody><tr><td>1</td><td>Vin</td><td>Питание нагрузки</td></tr><tr><td>2</td><td>LOAD</td><td>Коммутируемый выход на клапан или нагрузку</td></tr><tr><td>3</td><td>Operator Control Input</td><td>Вход штатной (ручной) команды, измеряется платой</td></tr><tr><td>4</td><td>GND</td><td>Возврат</td></tr></tbody></table><h3 id="sens1-sens8" tabindex="-1">SENS1…SENS8 <a class="header-anchor" href="#sens1-sens8" aria-label="Permalink to &quot;SENS1…SENS8&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th><th>Описание</th></tr></thead><tbody><tr><td>1</td><td>V_SENSE</td><td>Линия MAX14906: питание датчика и чтение его выхода</td></tr><tr><td>2</td><td>—</td><td>Назначение уточняется по схеме перед изготовлением жгута</td></tr><tr><td>3</td><td>GND</td><td>Возврат</td></tr></tbody></table><h3 id="c-sens1-c-sens4" tabindex="-1">C_SENS1…C_SENS4 <a class="header-anchor" href="#c-sens1-c-sens4" aria-label="Permalink to &quot;C_SENS1…C_SENS4&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Конт.</th><th>Сигнал</th><th>Описание</th></tr></thead><tbody><tr><td>1</td><td>Vin</td><td>Питание датчика</td></tr><tr><td>2</td><td>Измеряемый возврат</td><td>Ток датчика через шунт 2 Ом на GND</td></tr><tr><td>3</td><td>GND</td><td>Прямая земля, ток через неё не измеряется</td></tr></tbody></table><p>Порядок контактов разъёмов CAN и шлейфовых разъёмов сверяется с платой перед изготовлением жгута.</p><h2 id="_7-описание-функции" tabindex="-1">7. Описание функций <a class="header-anchor" href="#_7-описание-функции" aria-label="Permalink to &quot;7. Описание функций&quot;">​</a></h2><h3 id="_7-1-питание-и-измерение-входа" tabindex="-1">7.1. Питание и измерение входа <a class="header-anchor" href="#_7-1-питание-и-измерение-входа" aria-label="Permalink to &quot;7.1. Питание и измерение входа&quot;">​</a></h3><p>Vin поступает через XT30 на TVS-защиту и DC/DC-модуль 5 В; от него формируются шины 3,3 В. Входное напряжение измеряется через делитель, входной ток — через INA169 с шунтом 1 мОм (номинально 22 мВ/А на выходе). Прошивка публикует ток питания и напряжение шины 5 В в <code>CircuitStatus</code>.</p><h3 id="_7-2-нагрузки-и-bypass" tabindex="-1">7.2. Нагрузки и bypass <a class="header-anchor" href="#_7-2-нагрузки-и-bypass" aria-label="Permalink to &quot;7.2. Нагрузки и bypass&quot;">​</a></h3><p>Каждый канал LOAD собран на модуле ключа с двумя измерителями INA228: ток выхода и ток входа ручной команды. Канал работает в режиме включения/выключения или ШИМ по команде <code>ArrayCommand</code>.</p><p>В режиме bypass штатная команда проходит на клапан напрямую через нормально замкнутое реле, минуя управление платы. Bypass включён аппаратно, пока плата обесточена, перезагружается или не инициализирована; прошивка выключает его только когда готова управлять. В исполнении F103 bypass каналов LOAD3 и LOAD4 общий.</p><h3 id="_7-3-дискретные-входы-sens" tabindex="-1">7.3. Дискретные входы SENS <a class="header-anchor" href="#_7-3-дискретные-входы-sens" aria-label="Permalink to &quot;7.3. Дискретные входы SENS&quot;">​</a></h3><p>Линии SENS обслуживают четыре микросхемы MAX14906: две читают выходы датчиков, две подают датчикам питание. Плата может обесточить отдельный датчик, не затрагивая остальные, и отличает обесточенный датчик от разомкнутого.</p><p>Состояние входа публикуется в <code>hardpoint.Status</code>, поле <code>status</code> одинаково для PNP и NPN:</p><table tabindex="0"><thead><tr><th>Тип входа</th><th>Низкий уровень</th><th>Высокий уровень</th></tr></thead><tbody><tr><td>PNP</td><td>0</td><td>1</td></tr><tr><td>NPN</td><td>1</td><td>0</td></tr></tbody></table><p><code>1</code> — выход датчика проводит, <code>0</code> — не проводит; соответствие механическому срабатыванию зависит от исполнения датчика (NO/NC). Значение <code>65535</code> означает, что измерение недоступно. NPN-датчику нужна внешняя подтяжка входа.</p><h3 id="_7-4-токовые-входы-c-sens" tabindex="-1">7.4. Токовые входы C_SENS <a class="header-anchor" href="#_7-4-токовые-входы-c-sens" aria-label="Permalink to &quot;7.4. Токовые входы C_SENS&quot;">​</a></h3><p>Входы рассчитаны на датчики с токовым выходом 4–20 мА; ток измеряется INA228 на шунте 2 Ом. Каждому входу назначается роль: ток, давление или перемещение, с калибровкой по граничным токам датчика. Настройка описана в <a href="./ina228">руководстве по INA228</a>.</p><h3 id="_7-5-can-ethernet-usb" tabindex="-1">7.5. CAN, Ethernet, USB <a class="header-anchor" href="#_7-5-can-ethernet-usb" aria-label="Permalink to &quot;7.5. CAN, Ethernet, USB&quot;">​</a></h3><p>CAN построен на трансиверах TJA1042 с питанием 5 В; на плате есть места под терминаторы 120 Ом, которые устанавливаются только на конце сегмента. Ethernet (только H7) — PHY LAN8742A по RMII, адрес PHY 1 при установленном R82. USB-C (только H7) работает как USB 2.0 FS device.</p><h2 id="_8-интерфеис-can" tabindex="-1">8. Интерфейс CAN <a class="header-anchor" href="#_8-интерфеис-can" aria-label="Permalink to &quot;8. Интерфейс CAN&quot;">​</a></h2><p>Прошивка работает по DroneCAN; полный список параметров — на странице <a href="./firmware_am_node_default">прошивки</a>.</p><table tabindex="0"><thead><tr><th>Направление</th><th>Сообщение</th><th>Назначение</th></tr></thead><tbody><tr><td>Приём</td><td><code>uavcan.equipment.actuator.ArrayCommand</code></td><td>Команды каналов LOAD; номер актуатора задаётся параметром <code>loads.aid_N</code></td></tr><tr><td>Передача</td><td><code>uavcan.equipment.actuator.Status</code></td><td>Состояние каналов LOAD</td></tr><tr><td>Передача</td><td><code>uavcan.equipment.power.CircuitStatus</code></td><td>Токи и напряжения LOAD, ручных входов и питания платы</td></tr><tr><td>Передача</td><td><code>uavcan.equipment.hardpoint.Status</code></td><td>Состояние входов SENS</td></tr><tr><td>Передача</td><td><code>uavcan.equipment.air_data.StaticPressure</code></td><td>Давление с входа C_SENS в роли датчика давления</td></tr><tr><td>Передача</td><td><code>uavcan.equipment.range_sensor.Measurement</code></td><td>Перемещение с входа C_SENS в роли датчика длины</td></tr></tbody></table><h2 id="_9-адресация-на-плате" tabindex="-1">9. Адресация на плате <a class="header-anchor" href="#_9-адресация-на-плате" aria-label="Permalink to &quot;9. Адресация на плате&quot;">​</a></h2><h3 id="_9-1-max14906" tabindex="-1">9.1. MAX14906 <a class="header-anchor" href="#_9-1-max14906" aria-label="Permalink to &quot;9.1. MAX14906&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Устройство</th><th>A1:A0</th><th>Назначение</th></tr></thead><tbody><tr><td>S0</td><td>00</td><td>Чтение входов SENS</td></tr><tr><td>S1</td><td>01</td><td>Чтение входов SENS</td></tr><tr><td>S0V</td><td>10</td><td>Питание линий SENS</td></tr><tr><td>S1V</td><td>11</td><td>Питание линий SENS</td></tr></tbody></table><h3 id="i2c-addresses" tabindex="-1">9.2. INA228 <a class="header-anchor" href="#i2c-addresses" aria-label="Permalink to &quot;9.2. INA228 {#i2c-addresses}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Цепь</th><th>Адреса</th></tr></thead><tbody><tr><td>C_SENS1 / C_SENS2 / C_SENS3 / C_SENS4</td><td>0x40 / 0x41 / 0x42 / 0x43</td></tr><tr><td>LOAD1 / LOAD2 / LOAD3 / LOAD4, вход ручной команды</td><td>0x44 / 0x45 / 0x46 / 0x47</td></tr><tr><td>LOAD1 / LOAD2 / LOAD3 / LOAD4, выход</td><td>0x48 / 0x49 / 0x4A / 0x4B</td></tr></tbody></table><h2 id="_10-рекомендации-по-применению" tabindex="-1">10. Рекомендации по применению <a class="header-anchor" href="#_10-рекомендации-по-применению" aria-label="Permalink to &quot;10. Рекомендации по применению&quot;">​</a></h2><p><strong>Монтаж.</strong> Плата устанавливается внутри жёсткого герметичного корпуса на все монтажные отверстия. Жгуты не должны держать плату механически; разъёмы фиксируются или разгружаются от вибрации. Над модулем контроллера оставляется сервисный зазор.</p><p><strong>Питание.</strong> Перед платой ставятся предохранитель или eFuse и защита от переполюсовки: одного TVS недостаточно. Провода и предохранители выбираются по суммарному току всех LOAD и потреблению платы; для индуктивных клапанов предусматривается гашение выбросов.</p><p><strong>CAN.</strong> На каждом сегменте ровно два терминатора 120 Ом; терминатор платы включается, только если она стоит на конце сегмента.</p><p><strong>Безопасность.</strong> Аварийный останов выполняется независимой цепью, не через плату.</p><h2 id="_11-известные-ограничения" tabindex="-1">11. Известные ограничения <a class="header-anchor" href="#_11-известные-ограничения" aria-label="Permalink to &quot;11. Известные ограничения&quot;">​</a></h2><ul><li>В модуле ключа канала LOAD3 адрес INA228 входа ручной команды по схеме совпадает с адресом выхода LOAD2 (0x49); подключение проверяется на плате.</li><li>В исполнении F103 bypass каналов LOAD3 и LOAD4 общий; его полярность подтверждается на плате.</li><li>Назначение контакта 2 разъёмов SENS и порядок контактов разъёмов CAN уточняются по схеме.</li><li>Ethernet не изолирован; для внешнего порта нужны магнитная развязка и ESD-защита.</li><li>Внутренняя схема модуля ключа нагрузки не опубликована: положение шунта относительно цепи bypass проверяется по схеме модуля.</li></ul><h2 id="_12-история-документа" tabindex="-1">12. История документа <a class="header-anchor" href="#_12-история-документа" aria-label="Permalink to &quot;12. История документа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Версия</th><th>Дата</th><th>Изменения</th></tr></thead><tbody><tr><td>0.1</td><td>2026-06-05</td><td>Первичное описание по схеме и чертежу платы</td></tr><tr><td>0.2</td><td>2026-06-05</td><td>Исполнения H7/F103, назначение SENS, C_SENS, LOAD, bypass, адресация INA228 и MAX14906</td></tr><tr><td>0.3</td><td>2026-10-01</td><td>Структура даташита, характеристики, интерфейс CAN, известные ограничения</td></tr></tbody></table>`,56))])}const C=e(i,[["render",S]]);export{u as __pageData,C as default};
